<section class="settings__section" data-controller="notifications"
    data-notifications-url-value="<%= user_push_subscriptions_path(Current.user) %>"
    data-notifications-public-key-value="<%= ENV.fetch("VAPID_PUBLIC_KEY") %>"
    data-notifications-subscriptions-value="<%= Current.user.push_subscriptions.where(session: Current.session).pluck(:endpoint_digest, :id).to_h.to_json %>"
    data-action="focus@window->notifications#refresh">
  <heading>
    <h2 class="divider">Push Notifications</h2>
    <div>Get your tray notifications on this device, even when Fizzy is closed.</div>
  </heading>

  <div class="notifications__status panel" data-notifications-target="status" hidden>
    <p class="notifications__off-message">Push notifications are off on this device.</p>
    <p class="notifications__on-message">Push notifications are on for this device.</p>
    <button type="button" class="btn" data-notifications-target="enable" data-action="notifications#enable" hidden>Turn on notifications</button>
    <button type="button" class="btn" data-notifications-target="disable" data-action="notifications#disable" hidden>Turn off notifications</button>
    <p data-notifications-target="error" role="alert" hidden>Couldn’t update push notifications. Please try again.</p>
  </div>

  <div class="notifications-help__explainer" data-notifications-target="help" hidden>
    <p data-notifications-target="unsupported" hidden>Push notifications aren’t available in this browser.</p>
    <%= render "notifications/settings/browser" %>
    <%= render "notifications/settings/system" %>
    <%= render "notifications/settings/install" %>
  </div>
</section>
EOF
